_marks_lock=_marks_threading.Lock()
_marks_dashboard=None
_marks_dashboard_at=0.0

@router.get('/active-live-marks')
def active_live_marks():
    from .hilega_active_live_marks_v1 import load
    global _marks_dashboard,_marks_dashboard_at
    with _marks_lock:
        if _marks_dashboard is None or _marks_time.monotonic()-_marks_dashboard_at>=5:
            _marks_dashboard=project_directional_shadow_dashboard(_rows())
            _marks_dashboard_at=_marks_time.monotonic()
        dashboard=_marks_dashboard
    return load(dashboard)
